#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRY 4096
#define MAX_RESOURCE_ID 256
#define MAX_CALLBACK_URL 512
#define AUDIT_BUFFER_SIZE 8192

typedef struct {
    char resource_id[MAX_RESOURCE_ID];
    char callback_url[MAX_CALLBACK_URL];
    char region[64];
    int verbosity;
} cloud_request_t;

typedef struct {
    char buffer[AUDIT_BUFFER_SIZE];
    size_t offset;
    int format_mode; // 0=plaintext, 1=html_dashboard
} audit_logger_t;

static int is_valid_region(const char *region) {
    const char *valid[] = {"us-east-1", "us-west-2", "eu-west-1", "ap-south-1", NULL};
    for (int i = 0; valid[i]; i++) {
        if (strcmp(region, valid[i]) == 0) return 1;
    }
    return 0;
}

static int sanitize_resource_id(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    for (i = 0; input[i] && j < outlen - 1; i++) {
        char c = input[i];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
            output[j++] = c;
        }
    }
    output[j] = '\0';
    return (j > 0) ? 0 : -1;
}

static int encode_html_entity(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 6; i++) {
        switch (input[i]) {
            case '<': j += snprintf(output + j, outlen - j, "&lt;"); break;
            case '>': j += snprintf(output + j, outlen - j, "&gt;"); break;
            case '&': j += snprintf(output + j, outlen - j, "&amp;"); break;
            case '"': j += snprintf(output + j, outlen - j, "&quot;"); break;
            case '\'': j += snprintf(output + j, outlen - j, "&#x27;"); break;
            default: output[j++] = input[i]; break;
        }
    }
    output[j] = '\0';
    return 0;
}

static int format_audit_entry(audit_logger_t *logger, const char *action,
                              const char *resource, const char *detail) {
    char entry[MAX_LOG_ENTRY];
    time_t now = time(NULL);
    char timebuf[64];
    strftime(timebuf, sizeof(timebuf), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

    if (logger->format_mode == 1) {
        char safe_action[512];
        char safe_resource[512];
        encode_html_entity(action, safe_action, sizeof(safe_action));
        encode_html_entity(resource, safe_resource, sizeof(safe_resource));
        snprintf(entry, sizeof(entry),
            "<div class=\"audit-entry\"><span class=\"ts\">%s</span>"
            "<span class=\"action\">%s</span>"
            "<span class=\"resource\">%s</span>"
            "<span class=\"detail\">%s</span></div>\n",
            timebuf, safe_action, safe_resource, detail);
    } else {
        snprintf(entry, sizeof(entry), "[%s] %s resource=%s detail=%s\n",
                 timebuf, action, resource, detail);
    }

    size_t elen = strlen(entry);
    if (logger->offset + elen < AUDIT_BUFFER_SIZE) {
        memcpy(logger->buffer + logger->offset, entry, elen);
        logger->offset += elen;
        return 0;
    }
    return -1;
}

static int validate_callback_url(const char *url) {
    if (strncmp(url, "https://", 8) != 0) return -1;
    if (strlen(url) > MAX_CALLBACK_URL - 1) return -1;
    // Reject javascript: scheme even if somehow embedded
    if (strstr(url, "javascript:") != NULL) return -1;
    return 0;
}

int cloud_provision_resource(cloud_request_t *req, audit_logger_t *logger) {
    if (!req || !logger) return -1;

    // Validate region
    if (!is_valid_region(req->region)) {
        format_audit_entry(logger, "PROVISION_DENIED", req->resource_id,
                          "invalid region");
        return -1;
    }

    // Sanitize resource ID for storage
    char clean_id[MAX_RESOURCE_ID];
    if (sanitize_resource_id(req->resource_id, clean_id, sizeof(clean_id)) != 0) {
        format_audit_entry(logger, "PROVISION_DENIED", "[invalid]",
                          "malformed resource id");
        return -1;
    }

    // Validate callback URL
    if (validate_callback_url(req->callback_url) != 0) {
        format_audit_entry(logger, "PROVISION_DENIED", clean_id,
                          "invalid callback url");
        return -1;
    }

    // Build detail string including callback for audit trail
    char detail[1024];
    snprintf(detail, sizeof(detail), "region=%s callback=%s status=initiated",
             req->region, req->callback_url);

    // Log the provisioning action
    format_audit_entry(logger, "PROVISION_START", clean_id, detail);

    // ... actual provisioning logic would go here ...

    format_audit_entry(logger, "PROVISION_COMPLETE", clean_id,
                      "status=success");
    return 0;
}

int cloud_get_audit_html(audit_logger_t *logger, char *out, size_t outlen) {
    if (!logger || !out) return -1;
    snprintf(out, outlen,
        "<!DOCTYPE html><html><head><title>Audit Log</title></head>"
        "<body><h1>Cloud Audit Dashboard</h1>%.*s</body></html>",
        (int)logger->offset, logger->buffer);
    return 0;
}

// Example usage / test harness
int main(int argc, char **argv) {
    audit_logger_t logger;
    memset(&logger, 0, sizeof(logger));
    logger.format_mode = 1; // HTML dashboard mode

    cloud_request_t req;
    memset(&req, 0, sizeof(req));

    if (argc >= 4) {
        strncpy(req.resource_id, argv[1], MAX_RESOURCE_ID - 1);
        strncpy(req.callback_url, argv[2], MAX_CALLBACK_URL - 1);
        strncpy(req.region, argv[3], sizeof(req.region) - 1);
    } else {
        strncpy(req.resource_id, "vm-instance-001", MAX_RESOURCE_ID - 1);
        strncpy(req.callback_url, "https://hooks.example.com/notify", MAX_CALLBACK_URL - 1);
        strncpy(req.region, "us-east-1", sizeof(req.region) - 1);
    }

    cloud_provision_resource(&req, &logger);

    char html_output[16384];
    cloud_get_audit_html(&logger, html_output, sizeof(html_output));
    printf("%s\n", html_output);

    return 0;
}
